CHANGELOG = '## [0.258.0] - an opening\'s surround merges with its wall; its glass keeps its own\n\nThe walker, walking seed 9205 on 2026-10-26 (the factory\'s docs/findings/walk_2026-10-26_panel/, L7), on a window:\n"not consistent: textures". Its wall panel read as a lighter rectangle on the wall. The buildings\' merge left every\n`*_open<n>` slot whole, because "a window\'s pane may be glass, which Godot sorts per mesh". So each window kept its\nown mesh and its own shade beside a merged wall.\n\n### Changed\n- **`assets/godot/merge_buildings.gd`**:\n  - an opening merges with its unit like any static module;\n  - a TRANSPARENT surface (`_glass`: a BaseMaterial3D whose transparency is not disabled) goes into one mesh of its\n    own where its instance stood, `GlassR_<n>`, sorted as it always was;\n  - a slot carrying `interactive_id` (a door that opens, a breachable panel, a window that breaks) still stays whole.\n- The report counts `glass_surfaces` and `glass_meshes`. `merge_buildings.check` requires both, refuses glass\n  surfaces in no mesh, and counts the glass meshes among those that must be unwrapped.\n\n### Measured on the walker\'s level (the factory\'s docs/findings/opening_merge/)\n- 18 window surrounds merged: deli_a01 8, parking_garage 8, supermarket_a01 2. Their 23 glass surfaces sit in 23\n  meshes of their own.\n- The walker\'s window (L7) now reads as the wall\'s shade.\n- Priced with the control run twice: draws median -1 and at most -23 a heading, frame time within the controls\'\n  spread, worst heading 2,209 -> 2,186.\n- NOT fixed by this: the walker\'s door and breach seams (L5, L6), which are interactive slots.\n  - Refuted there: lightmap density (a re-bake at the wall\'s density changed no frame), and the texture restarting\n    (all world-triplanar).\n  - What is left is Zoo 1.126.0\'s casing strips over a -12 % / +13 % bake step: a choice for the walker.\n\n### Tests\n- `tests/unit/test_merge_buildings.py`:\n  - an opening is no longer kept whole;\n  - its glass goes to its own mesh;\n  - three refusals for a report without its glass counts.\n- `tests/unit/test_merge_buildings_godot.py`: a window slot with a pane merges in Godot, `GlassR_0` stands, and the\n  report counts it. 5 of the file\'s tests fail on 0.257.0.\n\n'
OLD_VERSION, NEW_VERSION = '0.257.0', '0.258.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
